-- Run separately after the three public schema files in a selected Supabase project.
-- Bucket configuration is data and is not generated by declarative schema diffs.
begin;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
    ('avatars', 'avatars', true, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
    ('listing-images', 'listing-images', true, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
    ('repair-images', 'repair-images', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy swapfix_images_insert_own on storage.objects for insert to authenticated
with check (
    bucket_id in ('avatars', 'listing-images', 'repair-images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
);

create policy swapfix_images_select_own on storage.objects for select to authenticated
using (
    bucket_id in ('avatars', 'listing-images', 'repair-images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
);

create policy swapfix_images_delete_own on storage.objects for delete to authenticated
using (
    bucket_id in ('avatars', 'listing-images', 'repair-images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
);

-- Uploads use unique filenames and do not overwrite objects. No UPDATE policy is needed.
-- Public avatars/listing images are readable by URL. repair-images remain owner-only.
-- Technician access to repair photos must be added with job-participant policies when Repair is built.
commit;
